<template><div class="work-items"><WorkspaceHero eyebrow="MY WORKSPACE" title="我的待办与提醒" description="集中查看需要补充、审核和核验的事项，优先处理临期任务。" />
  <section class="card work-toolbar"><div class="work-counts"><span>共 <b>{{data.counts?.total||0}}</b> 项</span><span>已逾期 <b>{{data.counts?.overdue||0}}</b></span><span>3 天内 <b>{{data.counts?.soon||0}}</b></span></div><el-select v-model="kind" aria-label="事项类型"><el-option label="全部类型" value="all"/><el-option v-for="(label,value) in labels" :key="value" :label="label" :value="value"/></el-select><el-select v-model="urgency" aria-label="紧急程度"><el-option label="全部期限" value="all"/><el-option label="已逾期" value="overdue"/><el-option label="3 天内到期" value="soon"/></el-select><el-button :loading="loading" @click="load">刷新待办</el-button></section>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><p class="work-note">{{data.notice}}</p><p v-if="data.limited" class="work-note">{{data.limitNotice}}</p>
  <section v-loading="loading"><el-empty v-if="!error&&!filtered.length" description="当前筛选下没有待处理事项，可调整筛选或刷新。"/>
  <article v-for="item in filtered" :key="item.key" class="card work-item"><div class="work-item-copy"><div class="work-item-meta"><span>{{labels[item.kind]}}</span><el-tag v-if="item.urgency!=='normal'" :type="item.urgency==='overdue'?'danger':'warning'" size="small">{{item.urgency==='overdue'?'已逾期':'3 天内到期'}}</el-tag><time v-if="item.dueAt">截止 {{format(item.dueAt)}}</time></div><h2>{{item.title}}</h2><p>{{item.description}}</p><small v-if="item.messageIds?.length>1">已合并 {{item.messageIds.length}} 条同类消息</small></div><el-button v-if="item.to" type="primary" plain @click="router.push(item.to)">前往处理</el-button><el-button v-else-if="item.messageIds" :loading="reading===item.key" @click="read(item)">标记已读</el-button></article></section>
</div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import WorkspaceHero from '@/components/WorkspaceHero.vue';import {getWorkItems} from '@/api/work-items';import {markAsRead} from '@/api/message';
const router=useRouter();const data=ref({items:[],counts:{}});const loading=ref(false);const error=ref('');const kind=ref('all');const urgency=ref('all');const reading=ref('');let version=0;
const labels={application:'申报待补充',approval:'审批待处理',growth:'成长任务',deadline:'申报临期',message:'未读消息'};
const filtered=computed(()=>data.value.items.filter(item=>(kind.value==='all'||item.kind===kind.value)&&(urgency.value==='all'||item.urgency===urgency.value)));
const format=value=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
async function load(){const current=++version;loading.value=true;error.value='';try{const result=await getWorkItems();if(current===version)data.value=result;}catch(err){if(current===version){data.value={items:[],counts:{}};error.value=err.message||'待办加载失败，请刷新重试';}}finally{if(current===version)loading.value=false;}}
async function read(item){if(reading.value)return;reading.value=item.key;try{await Promise.all(item.messageIds.map(id=>markAsRead(id)));await load();}catch(err){ElMessage.error(err.message||'未能标记全部消息，请刷新后重试');}finally{reading.value='';}}
onMounted(load);onBeforeUnmount(()=>{version++;});
</script>
<style scoped>
.work-toolbar {display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:20px;margin:18px 0;}.work-counts{display:flex;gap:20px;flex:1;font-size:13px;color:#63758b;}.work-counts b{font-size:20px;color:#1f3655;}.work-toolbar .el-select{width:160px;}.work-note{font-size:12px;color:#63758b;line-height:1.8;}.work-item{padding:22px;margin-top:14px;display:flex;align-items:center;justify-content:space-between;gap:20px;}.work-item-copy{min-width:0;}.work-item-meta{display:flex;align-items:center;flex-wrap:wrap;gap:12px;color:#63758b;font-size:12px;}.work-item h2{font-size:17px;margin:10px 0;color:#1f3655;overflow-wrap:anywhere;}.work-item p{font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;color:#42526b;}.work-item small{color:#63758b;}.work-item>.el-button{flex-shrink:0;}@media(max-width:600px){.work-toolbar .el-select{width:100%;}.work-counts{flex-basis:100%;}.work-item{align-items:flex-start;flex-direction:column;padding:18px;}}
</style>
